    }

    clear() {
        this.removeEntries(() => true)
    }

    private readonly handleDataServiceChanged = () => {
        const nextProjectKey = projectKey(this.dataService)
        if (nextProjectKey === this.currentProjectKey) return

        this.currentProjectKey = nextProjectKey
        this.clear()
    }

    private readonly closeTopPopup = () => {
        const topEntry = this.entries.at(-1)
        if (!topEntry) return

        this.close(topEntry.id)
    }

    private findCardDetails(cardInternalId: string) {
        return this.entries.find((entry): entry is CardDetailsPopupEntry => (
            entry.kind === 'card-details' && entry.cardInternalId === cardInternalId
        ))
    }

    private openCardDetails(
        cardInternalId: string,
        anchorElement: HTMLElement,
        diffSelection: CardDetailsDiffSelection | null,
    ) {
        const entry: CardDetailsPopupEntry = {
            anchorElement,
            cardInternalId,
            diffSelection,
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-details-popup-${this.nextId}`,
            kind: 'card-details',
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    private removeEntries(shouldRemove: (entry: CardPopupEntry) => boolean) {
        const removedEntries = this.entries.filter(shouldRemove)
        if (removedEntries.length === 0) return

        removedEntries.forEach(({ fallbackAnchorElement }) => fallbackAnchorElement.remove())
        this.setEntries(this.entries.filter((entry) => !shouldRemove(entry)))
    }

    private replaceEntry(replacement: CardPopupEntry) {
        this.setEntries(this.entries.map((entry) => entry.id === replacement.id ? replacement : entry))
    }

    private requireCardDetails(id: string) {
        const entry = this.entries.find((candidate): candidate is CardDetailsPopupEntry => (
            candidate.id === id && candidate.kind === 'card-details'
        ))
        if (!entry) throw new Error(`Card details popup does not exist: ${id}`)

        return entry
    }

    private setEntries(entries: CardPopupEntry[]) {
        this.entries = entries
        this.reconcileMobileBackDismissRegistrations()
        this.dispatchEvent(new Event(CARD_POPUPS_CHANGED_EVENT))
    }

    private reconcileMobileBackDismissRegistrations() {
        const requiredRegistrationCount = this.mobileBackDismissEnabled ? this.entries.length : 0
        const obsoleteRegistrationIds = this.mobileBackDismissRegistrationIds.slice(requiredRegistrationCount)
        this.mobileBackDismissRegistrationIds = this.mobileBackDismissRegistrationIds.slice(0, requiredRegistrationCount)
        obsoleteRegistrationIds.forEach((registrationId) => this.mobileBackDismissService.unregister(registrationId))

        const missingRegistrationCount = requiredRegistrationCount - this.mobileBackDismissRegistrationIds.length
        const newRegistrationIds = Array.from({ length: missingRegistrationCount }, () => {
            const registrationId = `${MOBILE_BACK_DISMISS_REGISTRATION_PREFIX}-${this.nextMobileBackDismissRegistrationId}`
            this.nextMobileBackDismissRegistrationId += 1
            this.mobileBackDismissService.register(registrationId, this.closeTopPopup)

            return registrationId
        })
        this.mobileBackDismissRegistrationIds = [...this.mobileBackDismissRegistrationIds, ...newRegistrationIds]
    }
}

export const cardPopupService = register(
    'cardPopupService',
    new CardPopupService(dataService, mobileBackDismissService),
)

export function subscribeCardPopups(onStoreChange: () => void) {
    cardPopupService.addEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)

    return () => cardPopupService.removeEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)
}

import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import { actionPromptDraftService } from '../../../../services/actions/action_prompt_draft_service'
import { cardAgentState } from '../../../../services/agents/card_agent_state'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'
import { resolveInitialActionId, type PersistedActionStates } from './action_popup_initial_action'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

/**
 * Badge id plus the title shown in its tooltip. The title comes from the live snapshot so it
 * follows a card renamed while the popup stays open, and falls back to the title captured in the
 * context when the card is not in the snapshot.
 */
function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return { id: 'Project', title: null }
    if (context.kind !== 'card') return { id: null, title: null }

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
    const card = cards.find(({ header }) => header.internalId === context.cardInternalId)

    return { id: card?.header.id ?? null, title: card?.header.title ?? context.title ?? null }
}

function resolveCardInternalId(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
    const card = context.cardInternalId
        ? cards.find(({ header }) => header.internalId === context.cardInternalId)
        : cards.find(({ path }) => path === context.file)

    return card?.header.internalId ?? context.cardInternalId ?? null
}

function resolveColumnDefaultActionId(context: ActionContext) {
    if (context.kind !== 'card' || !context.state) return undefined

    return dataService.getConfig()?.states.find(({ state }) => state === context.state)?.defaultActionId
}

function persistedActionStates(
    actions: ReturnType<typeof displayActionsForContext>,
    context: ActionContext,
    snapshot: ReturnType<typeof useProjectState>['snapshot'],
) {
    if (context.kind === 'project') {
        const conversations = dataService.agents.getProjectAgentConversationsSnapshot()

        return Object.fromEntries(actions.map(({ id }) => [
            id,
            cardAgentState(conversations.filter((conversation) => conversation.actionId === id)),
        ])) as PersistedActionStates
    }

    const cardInternalId = resolveCardInternalId(context, snapshot)
    if (!cardInternalId) return {}

    const conversations = dataService.agents.getAgentConversations(cardInternalId)

    return Object.fromEntries(actions.map(({ id }) => [
        id,
        cardAgentState(conversations.filter((conversation) => conversation.actionId === id)),
    ])) as PersistedActionStates
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    initialRunId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, initialRunId, onClose, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(() => resolveInitialActionId(
        actions,
        initialActionId,
        actionRunRegistry.getContextActiveSnapshot(effectiveContext),
        persistedActionStates(actions, effectiveContext, snapshot),
        resolveColumnDefaultActionId(effectiveContext),
    ))
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const { id: target, title: targetTitle } = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleClose = () => {
        actionPromptDraftService.deleteEmptyDrafts()
        onClose()
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            initialRunId={selectedAction.id === initialActionId ? initialRunId : undefined}
            onClose={handleClose}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            targetTitle={targetTitle}
            titleId={titleId}
        />
    )
}

import { useEffect, useMemo } from 'react'
import { actionContextIdentity } from '../../../../data/action_context'
import {
    actionRunSettingsService,
} from '../../../../services/actions/action_run_settings_service'
import { AgentAction } from './agent_action'
import { ActionPopupFrame } from './action_popup_frame'
import { CommandAction } from './command_action'
import { createActionPopupBindings, worktreeValidationMessage } from './action_popup_runtime'
import type { ActionPopupContentProps, ActionPopupRuntime } from './action_popup_types'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame'

/** Selects the action-specific popup content while preserving its runtime for the selected action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext, initialRunId } = props
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : actionRunSettingsService.getSessionStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext, initialRunId),
        [action, assignmentContext, initialRunId],
    )
    useEffect(() => {
        bindings.usageValuesService.start()

        return () => {
            bindings.usageValuesService.stop()
            bindings.bindingStore.dispose()
        }
    }, [bindings])
    const runtime: ActionPopupRuntime = {
        ...bindings,
        runValidationError: worktreeValidationMessage(action, assignmentContext),
        settingsStore,
    }

    return (
        <ActionPopupFrame
            bindingStore={bindings.bindingStore}
            contentProps={props}
            conversationSearchService={bindings.conversationSearchService}
            conversationStore={bindings.conversationStore}
        >
            {action.type === 'agent'
                ? (
                    <AgentAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        popupEntryId={props.popupEntryId}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                ) : (
                    <CommandAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                )}
        </ActionPopupFrame>
    )
}

import { useMediaQuery, useTheme } from '@mui/material'
import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import {
    cardPopupService,
    subscribeCardPopups,
} from '../../../../services/card_popup_service'
import type { WorkspaceViewMode } from '../../../../services/project/workspace_view_service'
import { CardActionPopupHostEntry } from './card_action_popup_host_entry'
import { useWorkspaceView } from '../../../hooks/use_workspace_view'

/**
 * View-mode visibility. Diagram view hides every popup and runs its own. Stats view hides card
 * popups, but keeps the project agent popup, which stays usable there.
 */
function isEntryVisibleInView(context: ActionContext, viewMode: WorkspaceViewMode) {
    if (viewMode === 'diagrams') return false
    if (viewMode === 'stats') return context.kind === 'project'

    return true
}

/** Stable renderer for all service-owned card action popups. */
export function CardActionPopupHost() {
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const { viewMode } = useWorkspaceView()
    const entries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const topEntryId = entries.at(-1)?.id

    return entries.map((entry, stackPosition) => entry.kind === 'action' ? (
        <CardActionPopupHostEntry
            entry={entry}
            key={entry.id}
            stackPosition={stackPosition}
            visible={isEntryVisibleInView(entry.context, viewMode) && (!isMobile || entry.id === topEntryId)}
        />
    ) : null)
}

import { Button } from '@mui/material'
import { alpha } from '@mui/material/styles'
import Robot from 'mdi-material-ui/Robot'
import { useState, useSyncExternalStore } from 'react'
import { agentConversationService } from '../../services/agents/agent_conversation_service'
import { cardPopupService } from '../../services/card_popup_service'
import { useActiveActionRuns } from '../hooks/use_action_runs'
import { useActions } from '../hooks/use_actions'
import { MobileStatusRow } from './mobile_status_row'
import { RunningAgentsDetails } from './running_agents_details'
import type { RunningAgentDetailsItem } from './running_agents_details'
import { StatusDetailsSurface } from './status_details_surface'

function subscribeToRunningAgents(onStoreChange: () => void) {
    return agentConversationService.subscribe(onStoreChange)
}

function getRunningAgentsSnapshot() {
    return agentConversationService.getRunningAgents()
}

/** Shows the number of running agents and lists them in a popover when opened. */
interface RunningAgentsIndicatorProps {
    mobile?: boolean
}

export function RunningAgentsIndicator({ mobile = false }: RunningAgentsIndicatorProps) {
    const directRunningAgents = useSyncExternalStore(subscribeToRunningAgents, getRunningAgentsSnapshot, getRunningAgentsSnapshot)
    const activeActionRuns = useActiveActionRuns()
    const { actions } = useActions()
    const actionLabels = new Map(actions.map(({ id, label }) => [id, label]))
    const agents: RunningAgentDetailsItem[] = [
        ...directRunningAgents.map(({ id, label }) => ({ id, kind: 'plain' as const, label })),
        ...activeActionRuns.map(({ context, runId, rootActionId }): RunningAgentDetailsItem => (
            context.kind === 'card' && !!context.cardInternalId
                ? {
                    context,
                    id: runId,
                    kind: 'card-action',
                    label: actionLabels.get(rootActionId) ?? rootActionId,
                    rootActionId,
                    runId,
                    secondaryLabel: context.title,
                }
                : { id: runId, kind: 'plain', label: `Action ${rootActionId}` }
        )),
    ]
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)

    const handleOpen = (event: React.MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    const handleSelect = (agent: RunningAgentDetailsItem, rowAnchorElement: HTMLElement) => {
        if (agent.kind !== 'card-action') return

        handleClose()
        cardPopupService.openActionRun(agent.context, agent.rootActionId, agent.runId, rowAnchorElement)
    }

    return (
        <>
            {mobile ? (
                <MobileStatusRow
                    accessibleName={`Running agents: ${agents.length}`}
                    icon={<Robot sx={{ fontSize: 18 }} />}
                    label="Running agents"
                    onClick={handleOpen}
                    tone="text.secondary"
                    value={agents.length.toLocaleString('en-US')}
                />
            ) : (
                <Button
                    aria-label={`Running agents: ${agents.length}`}
                    onClick={handleOpen}
                    size="small"
                    startIcon={<Robot sx={{ fontSize: '14px !important' }} />}
                    sx={{
                        bgcolor: (theme) => alpha(theme.palette.primary.main, 0.14),
                        borderRadius: 99,
                        color: 'primary.main',
                        fontSize: 11.5,
                        height: 22,
                        minWidth: 0,
                        px: 1.25,
                        '&:hover': { bgcolor: (theme) => alpha(theme.palette.primary.main, 0.22) },
                    }}
                >
                    {agents.length} {agents.length === 1 ? 'agent' : 'agents'}
                </Button>
            )}
            <StatusDetailsSurface anchorElement={anchorElement} labelId="running-agents-details-title" mobile={mobile} onClose={handleClose}>
                <RunningAgentsDetails agents={agents} onSelect={handleSelect} />
            </StatusDetailsSurface>
        </>
    )
}

