    private handleActionRunEvent(event: ActionRunEvent) {
        if (event.type === 'agentState') {
            this.applyConversationStatus(event, event.status)
            return
        }

        if (event.type === 'run' && event.status in TERMINAL_CONVERSATION_STATUS) {
